catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

	var emp =  g_form.getValue('subject_person'); 
	if (!emp) {
		g_form.setValue("manager_name", '');
		g_form.setValue('employee_title','');
		return;
	}

	var ga = new GlideAjax('sn_hr_core.hr_ProducerUtils'); 
	ga.addParam('sysparm_name', 'getGlideRecordData'); 
	ga.addParam('sysparm_table_name', "sys_user");
	ga.addParam('sysparm_sys_id', emp); 
	ga.addParam('sysparm_fields', "manager,title"); 
	ga.getXML(function(serverResponse){
		var items = serverResponse.responseXML.getElementsByTagName("item");
		g_form.setValue("manager_name", '');
		g_form.setValue('employee_title','');
		for(var i = 0; i < items.length; i++) {
			var field = items[i].getAttribute("field");
			if (field == "manager") {
				g_form.setValue("manager_name", items[i].getAttribute("value"));
				//break;
			}
			else if(field == 'title'){
				g_form.setValue('employee_title',items[i].getAttribute('value'));
			}
		}
	});

}
